{
  "format": "piui-system",
  "version": 4,
  "name": "Dependency audit: agent, script and model call",
  "orchestrator": "audit",
  "agents": [
    {
      "id": "audit",
      "profile": {
        "name": "Dependency audit",
        "harness": "codex",
        "model": "REPLACE_WITH_AVAILABLE_MODEL",
        "permissionMode": "read-only",
        "instructions": "When called: read the package manifests of this repository. Input: task instructions. Output: the direct dependencies as evidence. Finish when every manifest is covered or report the concrete blocker. Do not change files.",
        "toolPolicy": {
          "rules": []
        },
        "serviceTier": "standard"
      },
      "task": "List every direct dependency declared in this repository's package manifests as \"name version\". Return a JSON object with a dependencies text list.",
      "resultFields": [
        {
          "name": "dependencies",
          "kind": "text-list"
        }
      ],
      "position": {
        "x": 60,
        "y": 100
      }
    },
    {
      "id": "count",
      "executor": {
        "type": "script",
        "runtime": "node",
        "source": "import { readFileSync } from 'node:fs';\n\n// stdin: {\"inputs\": {}, \"dependencies\": {\"audit\": {\"text\": ..., \"data\": {...}}}, \"step\": {\"id\", \"name\"}}\nconst input = JSON.parse(readFileSync(0, 'utf8'));\nconst names = (input.dependencies.audit?.data?.dependencies ?? []).map((entry) => String(entry).trim().split(/\\s+/)[0]);\nconst duplicates = [...new Set(names.filter((name, index) => names.indexOf(name) !== index))];\n// One JSON object on stdout is the step result, checked against resultFields.\nconsole.log(JSON.stringify({ total: names.length, duplicates }));\n",
        "timeoutSeconds": 30
      },
      "profile": {
        "name": "Count dependencies",
        "harness": "codex",
        "model": "script",
        "permissionMode": "read-only",
        "instructions": "",
        "toolPolicy": {
          "rules": []
        }
      },
      "task": "Count the dependency list and report duplicated package names. Deterministic: no model is involved.",
      "resultFields": [
        {
          "name": "total",
          "kind": "number"
        },
        {
          "name": "duplicates",
          "kind": "text-list"
        }
      ],
      "position": {
        "x": 340,
        "y": 100
      }
    },
    {
      "id": "summary",
      "executor": {
        "type": "llm"
      },
      "profile": {
        "name": "Audit summary",
        "harness": "codex",
        "model": "REPLACE_WITH_AVAILABLE_MODEL",
        "permissionMode": "read-only",
        "instructions": "Write for maintainers. State only what the dependency results show.",
        "toolPolicy": {
          "rules": []
        },
        "serviceTier": "standard"
      },
      "task": "Summarize the dependency audit in three sentences: how many direct dependencies there are, which names are duplicated, and what a maintainer should check first.",
      "inputBindings": [
        {
          "sourceStepId": "count",
          "field": "total",
          "name": "total"
        },
        {
          "sourceStepId": "count",
          "field": "duplicates",
          "name": "duplicates"
        }
      ],
      "position": {
        "x": 620,
        "y": 100
      }
    }
  ],
  "connections": [
    {
      "from": "audit",
      "to": "count",
      "kind": "result"
    },
    {
      "from": "audit",
      "to": "summary",
      "kind": "result"
    },
    {
      "from": "count",
      "to": "summary",
      "kind": "result"
    }
  ]
}

